{"path":"effect/main.gd","content":"extends Node
## Persistent player-interaction field and grass deformation entry point.
## The host calls configure once, then step before each requested frame.

var scene_root: Node
var test_input: Dictionary = {}
var elapsed_s := 0.0
var step_index := 0

var patch_origin := Vector2(-4.0, -4.0)
var patch_size := 8.0
var field_width := 64
var field_height := 64
var texel_size := Vector2(0.125, 0.125)
var field: PackedFloat32Array = PackedFloat32Array()

var radius_m := 0.95
var interaction_strength := 0.95
var persistence_60hz := 0.92
var bend_m := 0.35
var flatten_m := 0.10
var active_until_s := 2.0
var keyframes: Array = []
var player_xz := Vector2(-3.0, 0.0)
var player_velocity_xz := Vector2.ZERO


func configure(root: Node, inputs: Dictionary) -> void:
	scene_root = root
	test_input = inputs
	elapsed_s = 0.0
	step_index = 0

	var patch: Dictionary = inputs.get("patch", {})
	var origin: Array = patch.get("origin_xz_m", [-4.0, -4.0])
	var resolution: Array = patch.get("resolution", [64, 64])
	patch_origin = Vector2(float(origin[0]), float(origin[1]))
	patch_size = float(patch.get("size_m", 8.0))
	field_width = int(resolution[0])
	field_height = int(resolution[1])
	texel_size = Vector2(patch_size / float(field_width), patch_size / float(field_height))
	field.resize(field_width * field_height * 4)
	field.fill(0.0)

	var interaction: Dictionary = inputs.get("interaction", {})
	radius_m = float(interaction.get("radius_m", 0.95))
	interaction_strength = float(interaction.get("strength", 0.95))
	persistence_60hz = float(interaction.get("persistence_per_60hz_step", 0.92))
	bend_m = float(interaction.get("bend_m", 0.35))
	flatten_m = float(interaction.get("flatten_m", 0.10))
	active_until_s = float(inputs.get("interaction_active_until_s", 2.0))
	keyframes = inputs.get("player_keyframes", []).duplicate(true)
	player_xz = _trajectory_position(0.0)
	player_velocity_xz = Vector2.ZERO
	_push_visual_state()


func step(dt: float) -> void:
	if dt <= 0.0:
		return
	var previous_position := player_xz
	elapsed_s += dt
	step_index += 1
	player_xz = _trajectory_position(elapsed_s)
	player_velocity_xz = (player_xz - previous_position) / dt

	# Persistence is specified per 1/60 second, so this remains correct for
	# other fixed time steps as well.
	var decay := pow(clampf(persistence_60hz, 0.0, 1.0), dt * 60.0)
	for i in range(field.size()):
		field[i] *= decay

	# The interactor is removed at exactly the cutoff time.  In particular,
	# step 120 for the supplied input only decays the history.
	if elapsed_s < active_until_s - 0.0000001:
		_stamp_player(player_xz)
	_push_visual_state()


func _trajectory_position(time_s: float) -> Vector2:
	if keyframes.is_empty():
		return Vector2.ZERO
	var first: Dictionary = keyframes[0]
	if time_s <= float(first.get("time_s", 0.0)):
		var p0: Array = first.get("position_xz_m", [0.0, 0.0])
		return Vector2(float(p0[0]), float(p0[1]))
	for i in range(keyframes.size() - 1):
		var a: Dictionary = keyframes[i]
		var b: Dictionary = keyframes[i + 1]
		var ta := float(a.get("time_s", 0.0))
		var tb := float(b.get("time_s", ta))
		if time_s <= tb:
			var pa: Array = a.get("position_xz_m", [0.0, 0.0])
			var pb: Array = b.get("position_xz_m", [0.0, 0.0])
			var alpha := clampf((time_s - ta) / maxf(tb - ta, 0.000001), 0.0, 1.0)
			return Vector2(float(pa[0]), float(pa[1])).lerp(Vector2(float(pb[0]), float(pb[1])), alpha)
	var last: Dictionary = keyframes[keyframes.size() - 1]
	var pl: Array = last.get("position_xz_m", [0.0, 0.0])
	return Vector2(float(pl[0]), float(pl[1]))


func _stamp_player(center: Vector2) -> void:
	if radius_m <= 0.0 or interaction_strength <= 0.0:
		return
	# Restrict work to texel centers intersecting the circular brush.
	var min_x := maxi(0, int(floor((center.x - radius_m - patch_origin.x) / texel_size.x - 0.5)))
	var max_x := mini(field_width - 1, int(ceil((center.x + radius_m - patch_origin.x) / texel_size.x - 0.5)))
	var min_y := maxi(0, int(floor((center.y - radius_m - patch_origin.y) / texel_size.y - 0.5)))
	var max_y := mini(field_height - 1, int(ceil((center.y + radius_m - patch_origin.y) / texel_size.y - 0.5)))
	if min_x > max_x or min_y > max_y:
		return
	for y in range(min_y, max_y + 1):
		for x in range(min_x, max_x + 1):
			var world_xz := patch_origin + Vector2((float(x) + 0.5) * texel_size.x, (float(y) + 0.5) * texel_size.y)
			var delta := world_xz - center
			var distance := delta.length()
			if distance >= radius_m:
				continue
			# Hermite falloff has zero slope at both center and radius, avoiding
			# blocky rings while retaining a strong readable trail.
			var t := clampf(distance / radius_m, 0.0, 1.0)
			var falloff := 1.0 - t * t * (3.0 - 2.0 * t)
			var amount := interaction_strength * falloff
			var direction := delta / distance if distance > 0.000001 else _fallback_direction()
			var offset := (y * field_width + x) * 4
			var old_amount := field[offset + 2]
			# A max-composite brush is frame-rate stable: revisiting refreshes a
			# texel rather than accumulating beyond the requested strength.
			if amount >= old_amount:
				field[offset] = direction.x * amount
				field[offset + 1] = direction.y * amount
				field[offset + 2] = amount
				field[offset + 3] = 0.0


func _fallback_direction() -> Vector2:
	if player_velocity_xz.length_squared() > 0.000001:
		return player_velocity_xz.normalized()
	return Vector2.RIGHT


func _push_visual_state() -> void:
	# Populated further by the visual/deformation steps. Keeping player motion
	# synchronized here preserves the supplied trajectory in the host scene.
	if scene_root == null:
		return
	var player := scene_root.get_node_or_null("PlayerProxy") as Node3D
	if player != null:
		player.position = Vector3(player_xz.x, 0.0, player_xz.y)


func sample() -> Dictionary:
	# Dictionary insertion order intentionally follows the requested schema.
	return {
		"step": step_index,
		"elapsed_s": elapsed_s,
		"field_rgba": Array(field),
		"positions": [],
		"normals": []
	}
"}

