	# step 120 for the supplied input only decays the history.
	if elapsed_s < active_until_s - 0.0000001:
		_stamp_player(player_xz)
	_push_visual_state()


func _trajectory_position(time_s: float) -> Vector2:
	if keyframes.is_empty():
		return Vector2.ZERO
	var first: Dictionary = keyframes[0]
	if time_s <= float(first.get("time_s", 0.0)):
		var p0: Array = first.get("position_xz_m", [0.0, 0.0])
		return Vector2(float(p0[0]), float(p0[1]))
	for i in range(keyframes.size() - 1):
		var a: Dictionary = keyframes[i]
		var b: Dictionary = keyframes[i + 1]
		var ta := float(a.get("time_s", 0.0))
		var tb := float(b.get("time_s", ta))
		if time_s <= tb:
			var pa: Array = a.get("position_xz_m", [0.0, 0.0])
			var pb: Array = b.get("position_xz_m", [0.0, 0.0])
			var alpha := clampf((time_s - ta) / maxf(tb - ta, 0.000001), 0.0, 1.0)
