	var pl: Array = last.get("position_xz_m", [0.0, 0.0])
	return Vector2(float(pl[0]), float(pl[1]))


func _stamp_player(center: Vector2) -> void:
	if radius_m <= 0.0 or interaction_strength <= 0.0:
		return
	# Restrict work to texel centers intersecting the circular brush.
	var min_x := maxi(0, int(floor((center.x - radius_m - patch_origin.x) / texel_size.x - 0.5)))
	var max_x := mini(field_width - 1, int(ceil((center.x + radius_m - patch_origin.x) / texel_size.x - 0.5)))
	var min_y := maxi(0, int(floor((center.y - radius_m - patch_origin.y) / texel_size.y - 0.5)))
	var max_y := mini(field_height - 1, int(ceil((center.y + radius_m - patch_origin.y) / texel_size.y - 0.5)))
	if min_x > max_x or min_y > max_y:
		return
	for y in range(min_y, max_y + 1):
		for x in range(min_x, max_x + 1):
			var world_xz := patch_origin + Vector2((float(x) + 0.5) * texel_size.x, (float(y) + 0.5) * texel_size.y)
			var delta := world_xz - center
			var distance := delta.length()
			if distance >= radius_m:
				continue
			# Hermite falloff has zero slope at both center and radius, avoiding
			# blocky rings while retaining a strong readable trail.
			var t := clampf(distance / radius_m, 0.0, 1.0)
			var falloff := 1.0 - t * t * (3.0 - 2.0 * t)
			var amount := interaction_strength * falloff
			var direction := delta / distance if distance > 0.000001 else _fallback_direction()
			var offset := (y * field_width + x) * 4
			var old_amount := field[offset + 2]
			# A max-composite brush is frame-rate stable: revisiting refreshes a
			# texel rather than accumulating beyond the requested strength.
			if amount >= old_amount:
				field[offset] = direction.x * amount
				field[offset + 1] = direction.y * amount
				field[offset + 2] = amount
				field[offset + 3] = 0.0


func _fallback_direction() -> Vector2:
	if player_velocity_xz.length_squared() > 0.000001:
		return player_velocity_xz.normalized()
	return Vector2.RIGHT


func _push_visual_state() -> void:
	# Populated further by the visual/deformation steps. Keeping player motion
	# synchronized here preserves the supplied trajectory in the host scene.
	if scene_root == null:
		return
	var player := scene_root.get_node_or_null("PlayerProxy") as Node3D
	if player != null:
		player.position = Vector3(player_xz.x, 0.0, player_xz.y)


func sample() -> Dictionary:
	# Dictionary insertion order intentionally follows the requested schema.
	return {
		"step": step_index,
		"elapsed_s": elapsed_s,
		"field_rgba": Array(field),
		"positions": [],
		"normals": []
	}
"}

